// Backups made by PR #1 must stay restorable. These fixtures are real files: four were
// downloaded by Chromium from the app during PR #1's browser tests, and one was generated by
// the exact export code of PR #1's first commit (c3d8d63).

import { readFileSync } from 'fs';
import { afterEach, describe, expect, it } from 'vitest';
import { makeStorage } from '../testing/storage';
import { analyzeBackup, createRestoreEngine, readDataKeys } from './dataRestore';
import { createMemorySafetyStore } from './safetyStore';
import { resetGuardForTests } from './storageGuard';

const read = (name: string) => readFileSync(`fixtures/exports/${name}`, 'utf8');
const DELI_KEYS = ['inventory_currentOrder', 'inventory_deliName', 'inventory_products', 'inventory_suppliers', 'language', 'theme'];
const context = () => ({ now: new Date(), origin: 'o', href: 'h', userAgent: 'u', appName: 'DeliOrderNYC', appVersion: '0' });

afterEach(() => resetGuardForTests());

const restoreFixture = async (name: string) => {
  const text = read(name);
  const analysis = await analyzeBackup(text);
  const device = makeStorage({ inventory_deliName: 'Device', other_app_auth: 'device-only-token' });
  const engine = createRestoreEngine({ storage: device.storage, store: createMemorySafetyStore(), exportContext: context });
  const outcome = await engine.restore(analysis.target);
  return { text, analysis, device, outcome };
};

describe('PR #1 backups', () => {
  it.each([
    ['pr1-b291176-arizona-demo.json', 'verified'],
    ['pr1-c3d8d63-arizona-demo.json', 'verified'],
    ['pr1-b291176-opt-in-other-app.json', 'verified'],
    ['pr1-c3d8d63-legacy-with-other-app-key.json', 'verified'],
    ['pr1-b291176-no-web-crypto.json', 'unverified'],
  ])('%s is %s and restores all deli data exactly', async (name, status) => {
    const { text, analysis, device, outcome } = await restoreFixture(name);
    expect(analysis.verification.status).toBe(status);
    expect(analysis.canRestore).toBe(true);
    expect(analysis.requiresAcknowledgement).toBe(status === 'unverified');
    expect(outcome.status).toBe('restored');
    const raw = JSON.parse(text).raw;
    const restored = readDataKeys(device.storage);
    expect(Object.keys(restored).sort()).toEqual(DELI_KEYS);
    for (const key of DELI_KEYS) expect(restored[key]).toBe(raw[key]); // byte-for-byte
    const products = JSON.parse(restored.inventory_products);
    expect(products).toHaveLength(141);
    expect(JSON.parse(restored.inventory_suppliers)).toHaveLength(13);
  });

  it('the Arizona demo backups still total $77.98', async () => {
    for (const name of ['pr1-b291176-arizona-demo.json', 'pr1-c3d8d63-arizona-demo.json']) {
      const { device } = await restoreFixture(name);
      const data = readDataKeys(device.storage);
      const products = JSON.parse(data.inventory_products) as { id: string; costPrice: number }[];
      const order = JSON.parse(data.inventory_currentOrder) as { items: { productId: string; quantity: number }[] };
      const total = order.items.reduce((sum, item) => sum + products.find(p => p.id === item.productId)!.costPrice * item.quantity, 0);
      expect(total.toFixed(2)).toBe('77.98');
      resetGuardForTests();
    }
  });

  it('legacy exports that swept up other apps’ data: that data is skipped and never written', async () => {
    for (const name of ['pr1-c3d8d63-legacy-with-other-app-key.json', 'pr1-b291176-opt-in-other-app.json']) {
      const { analysis, device } = await restoreFixture(name);
      expect(analysis.skipped).toEqual([{ key: 'other_app_auth', reason: 'other-app' }]);
      expect(analysis.target.other_app_auth).toBeUndefined();
      // The device's own unrelated value is untouched; the file's value was never written.
      expect(device.dump().other_app_auth).toBe('device-only-token');
      resetGuardForTests();
    }
  });
});
